import {render,screen,fireEvent,waitFor,cleanup} from '@testing-library/react';
import {it,expect,vi,afterEach} from 'vitest';
import {ConnectedPaidJourneyDraft,type JourneyDraftClient} from './ConnectedPaidJourneyDraft';
import {createRuntimeClient,PaidJourneyDraftError,PublicationError,type PaidJourneyOwnerPublication,type PaidJourneyVersionHistory,type PaidJourneyRollbackState,type PaidJourneyRollbackReceipt,type PaidJourneyPublicationState,type PaidJourneyPublicationReceipt,type PaidJourneyDraftState,type PaidJourneyDraftInput,type PaidJourneyOwnerDraft,type ServiceRow,type BusinessProfileRead} from '@lumin/runtime-client';
afterEach(()=>{cleanup();window.history.replaceState(null,'','/');});
const tenant='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',flow='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',serviceId='cccccccc-cccc-4ccc-8ccc-cccccccccccc',other='dddddddd-dddd-4ddd-8ddd-dddddddddddd';
const service:ServiceRow={id:serviceId,tenant_id:tenant,name:'Cleaning visit',currency:'USD',duration_minutes:60,base_price:12500,active:true};
const profile:BusinessProfileRead={status:'initialized',profile:{schemaVersion:1,tenantId:tenant,businessType:'HOUSEKEEPING',templateVersion:1}};
const draft:PaidJourneyOwnerDraft={schemaVersion:1,tenantId:tenant,flowId:flow,revision:2,serviceId,name:'Stored housekeeping draft',presentation:{accentColor:'#0e7490',layout:'compact'},journey:{schemaVersion:1,stages:(['service','options','information','schedule','review_payment','confirmation'] as const).map(kind=>({id:kind,kind,label:String(kind),enabled:true}))}};
function fixture(){let auth=1,state:PaidJourneyDraftState={phase:'ready'};const client:JourneyDraftClient={authContextRevision:()=>auth,simpleOfferLocked:()=>state.phase==='unverified'||state.phase==='saving',businessProfile:vi.fn(async()=>profile),paidJourneyDraftState:()=>state,loadPaidJourneyDraft:vi.fn(async()=>{state={phase:'loaded',flowId:flow,revision:2,draft};return draft;}),savePaidJourneyDraft:vi.fn(async(_tenant:string,id:string,input:PaidJourneyDraftInput)=>{state={phase:'saved',flowId:id,revision:input.expectedRevision+1};return {schemaVersion:1 as const,tenantId:tenant,flowId:id,revision:input.expectedRevision+1};})};return{client,setState:(value:PaidJourneyDraftState)=>state=value,changeAuth:()=>auth++};}
const props={tenantId:tenant,role:'BUSINESS_OWNER',staging:true,services:[service],catalogLoading:false};
async function open(){fireEvent.click(screen.getByRole('button',{name:'Check journey editor availability'}));await screen.findByRole('form',{name:'Save ordered journey draft'});}
function edit(){fireEvent.change(screen.getByLabelText('Journey service'),{target:{value:serviceId}});fireEvent.change(screen.getByLabelText('Journey name'),{target:{value:'New housekeeping draft'}});}
async function load(){fireEvent.change(screen.getByLabelText('Journey draft ID'),{target:{value:flow}});fireEvent.click(screen.getByRole('button',{name:'Reload saved journey draft'}));await screen.findByText('Loaded journey draft revision 2.');}
it('requires an explicit matching Housekeeping profile before showing controls and never auto-writes',async()=>{const {client}=fixture();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);expect(screen.queryByLabelText('Journey name')).toBeNull();expect(client.businessProfile).not.toHaveBeenCalled();await open();expect(client.businessProfile).toHaveBeenCalledWith(tenant);expect(client.savePaidJourneyDraft).not.toHaveBeenCalled();expect(client.loadPaidJourneyDraft).not.toHaveBeenCalled();expect(screen.queryByRole('link')).toBeNull();expect(screen.getByText(/The hosted customer checkout/)).toBeVisible();});
it.each(['foreign','rental','malformed','uninitialized'] as const)('withholds editing for %s profile',async kind=>{const {client}=fixture();vi.mocked(client.businessProfile).mockResolvedValue(kind==='uninitialized'?{status:'uninitialized',tenantId:tenant}:kind==='foreign'?{status:'initialized',profile:{...profile.profile,tenantId:other}}:kind==='rental'?{status:'initialized',profile:{...profile.profile,businessType:'VEHICLE_RENTAL'}}:{status:'initialized',profile:{...profile.profile,private:'secret'}} as never);render(<ConnectedPaidJourneyDraft {...props} client={client}/>);fireEvent.click(screen.getByRole('button',{name:'Check journey editor availability'}));await screen.findByRole('alert');expect(screen.queryByLabelText('Journey name')).toBeNull();expect(client.savePaidJourneyDraft).not.toHaveBeenCalled();});
it('saves a new dedicated identity with reviewed ordering/design and reloads stored fields explicitly',async()=>{const {client}=fixture();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();edit();fireEvent.click(screen.getByRole('button',{name:'Swap schedule and customer information'}));fireEvent.change(screen.getByLabelText('Service step label'),{target:{value:'Choose cleaning'}});fireEvent.change(screen.getByLabelText('Journey accent'),{target:{value:'#0e7490'}});fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));await screen.findByText(/Saved journey draft revision 1/);const args=vi.mocked(client.savePaidJourneyDraft).mock.calls[0]!;expect(args[0]).toBe(tenant);expect(args[1]).toMatch(/^[0-9a-f-]{36}$/);expect(args[2]).toMatchObject({expectedRevision:0,serviceId,name:'New housekeeping draft',presentation:{accentColor:'#0e7490'}});expect(args[2].journey.stages.map(stage=>stage.kind)).toEqual(['service','options','information','schedule','review_payment','confirmation']);expect(client.loadPaidJourneyDraft).not.toHaveBeenCalled();fireEvent.click(screen.getByRole('button',{name:'Reload saved journey draft'}));await screen.findByText('Loaded journey draft revision 2.');expect(screen.getByLabelText('Journey name')).toHaveValue(draft.name);expect(client.loadPaidJourneyDraft).toHaveBeenCalledWith(tenant,args[1]);});
it('requires explicit review before replacing dirty edits by load or a different draft identity',async()=>{const {client}=fixture();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();fireEvent.change(screen.getByLabelText('Journey name'),{target:{value:'Private unsaved edit'}});fireEvent.click(screen.getByRole('button',{name:'Reload saved journey draft'}));expect(client.loadPaidJourneyDraft).toHaveBeenCalledTimes(1);fireEvent.click(screen.getByRole('button',{name:'Keep journey edits'}));fireEvent.change(screen.getByLabelText('Journey draft ID'),{target:{value:other}});expect(screen.getByLabelText('Journey name')).toHaveValue('Private unsaved edit');expect(screen.getByLabelText('Journey draft ID')).toHaveValue(flow);fireEvent.click(screen.getByRole('button',{name:'Keep current journey'}));expect(screen.getByLabelText('Journey name')).toHaveValue('Private unsaved edit');fireEvent.change(screen.getByLabelText('Journey draft ID'),{target:{value:other}});fireEvent.click(screen.getByRole('button',{name:'Discard edits and change journey ID'}));expect(screen.getByLabelText('Journey draft ID')).toHaveValue(other);expect(screen.getByLabelText('Journey name')).toHaveValue('');expect(client.loadPaidJourneyDraft).toHaveBeenCalledTimes(1);expect(client.savePaidJourneyDraft).not.toHaveBeenCalled();});
it('discards locally only to the last explicit loaded baseline and previews supported widths without requests',async()=>{const {client}=fixture();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();fireEvent.change(screen.getByLabelText('Journey name'),{target:{value:'Unsaved'}});fireEvent.click(screen.getByRole('button',{name:'Discard unsaved journey edits'}));expect(screen.getByLabelText('Journey name')).toHaveValue(draft.name);expect(client.loadPaidJourneyDraft).toHaveBeenCalledTimes(1);for(const size of ['Mobile','Tablet','Desktop']){fireEvent.click(screen.getByRole('button',{name:size+' journey preview'}));expect(screen.getByRole('button',{name:size+' journey preview'})).toHaveAttribute('aria-pressed','true');expect(screen.getByLabelText(size+' journey preview frame')).toHaveStyle({width:'100%',minWidth:'0',boxSizing:'border-box'});}expect(client.savePaidJourneyDraft).not.toHaveBeenCalled();});
it('retains edits and refuses automatic conflict overwrite until explicit reload review',async()=>{const {client,setState}=fixture();vi.mocked(client.savePaidJourneyDraft).mockImplementation(async()=>{setState({phase:'conflict',flowId:flow});throw new PaidJourneyDraftError('conflict','private-provider-details');});render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();fireEvent.change(screen.getByLabelText('Journey name'),{target:{value:'Keep my edits'}});fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));await screen.findByText(/Stored journey revision could not/);expect(screen.getByLabelText('Journey name')).toHaveValue('Keep my edits');expect(screen.getByRole('button',{name:'Save journey draft'})).toBeDisabled();expect(document.body.textContent).not.toContain('private-provider-details');expect(client.loadPaidJourneyDraft).toHaveBeenCalledTimes(1);fireEvent.click(screen.getByRole('button',{name:'Reload saved journey draft'}));fireEvent.click(screen.getByRole('button',{name:'Discard edits and reload journey'}));await screen.findByText('Loaded journey draft revision 2.');expect(screen.getByLabelText('Journey name')).toHaveValue(draft.name);expect(client.savePaidJourneyDraft).toHaveBeenCalledTimes(1);});
it('keeps unknown save locked, preserving edits and the dedicated identity without retry/load/discard',async()=>{const {client,setState}=fixture();vi.mocked(client.savePaidJourneyDraft).mockImplementation(async(_tenant,id)=>{setState({phase:'unverified',flowId:id});throw new PaidJourneyDraftError('unknown','private-provider-details');});render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();edit();fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));await screen.findByText(/Journey save outcome is unverified/);expect(screen.getByLabelText('Journey name')).toHaveValue('New housekeeping draft');expect(screen.getByRole('button',{name:'Save journey draft'})).toBeDisabled();expect(screen.getByRole('button',{name:'Reload saved journey draft'})).toBeDisabled();expect(screen.getByRole('button',{name:'Discard unsaved journey edits'})).toBeDisabled();expect(client.loadPaidJourneyDraft).not.toHaveBeenCalled();expect(client.savePaidJourneyDraft).toHaveBeenCalledTimes(1);expect(document.body.textContent).not.toContain('private-provider-details');});
it.each(['profile','load','save'] as const)('drops late %s results on tenant change without exposing previous drafts',async kind=>{const {client}=fixture();let finish!:(value:unknown)=>void;const view=render(<ConnectedPaidJourneyDraft {...props} client={client}/>);if(kind==='profile')vi.mocked(client.businessProfile).mockImplementation(()=>new Promise(resolve=>finish=resolve as typeof finish));else await open();if(kind==='load'){vi.mocked(client.loadPaidJourneyDraft).mockImplementation(()=>new Promise(resolve=>finish=resolve as typeof finish));fireEvent.change(screen.getByLabelText('Journey draft ID'),{target:{value:flow}});fireEvent.click(screen.getByRole('button',{name:'Reload saved journey draft'}));}else if(kind==='save'){vi.mocked(client.savePaidJourneyDraft).mockImplementation(()=>new Promise(resolve=>finish=resolve as typeof finish));edit();fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));}else fireEvent.click(screen.getByRole('button',{name:'Check journey editor availability'}));await waitFor(()=>expect(finish).toBeTypeOf('function'));view.rerender(<ConnectedPaidJourneyDraft {...props} tenantId={other} services={[{...service,tenant_id:other}]} client={client}/>);finish(kind==='profile'?profile:kind==='load'?draft:{schemaVersion:1,tenantId:tenant,flowId:flow,revision:1});await waitFor(()=>expect(screen.queryByLabelText('Journey name')).toBeNull());expect(document.body.textContent).not.toContain(draft.name);expect(document.body.textContent).not.toContain(flow);});
it('clears private draft fields on same-client auth revision change and forbids stale action without rerender',async()=>{const {client,changeAuth}=fixture();const view=render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();fireEvent.change(screen.getByLabelText('Journey name'),{target:{value:'Private old actor edit'}});changeAuth();fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));expect(client.savePaidJourneyDraft).not.toHaveBeenCalled();view.rerender(<ConnectedPaidJourneyDraft {...props} client={client}/>);expect(screen.queryByLabelText('Journey name')).toBeNull();expect(document.body.textContent).not.toContain('Private old actor edit');expect(document.body.textContent).not.toContain(flow);});
it('does not show controls for nonowner/nonstaging or accept a removed/foreign service',async()=>{const {client}=fixture();const view=render(<ConnectedPaidJourneyDraft {...props} role="BUSINESS_STAFF" client={client}/>);expect(screen.queryByRole('button')).toBeNull();view.rerender(<ConnectedPaidJourneyDraft {...props} staging={false} client={client}/>);expect(screen.queryByRole('button')).toBeNull();view.rerender(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();edit();view.rerender(<ConnectedPaidJourneyDraft {...props} services={[{...service,tenant_id:other}]} client={client}/>);expect(screen.getByRole('button',{name:'Save journey draft'})).toBeDisabled();fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));expect(client.savePaidJourneyDraft).not.toHaveBeenCalled();});

it('restores only a URL locator after refresh and verifies saved draft through authenticated load',async()=>{const {client}=fixture();const first=render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();edit();fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));await screen.findByText(/Saved journey draft revision 1/);const id=new URL(window.location.href).searchParams.get('journeyDraft');expect(id).toMatch(/^[0-9a-f-]{36}$/);expect(new URL(window.location.href).searchParams.get('journeyTenant')).toBe(tenant);first.unmount();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);expect(screen.queryByLabelText('Journey name')).toBeNull();expect(client.loadPaidJourneyDraft).not.toHaveBeenCalled();await open();fireEvent.click(screen.getByRole('button',{name:'Reload saved journey draft'}));await screen.findByText('Loaded journey draft revision 2.');expect(client.loadPaidJourneyDraft).toHaveBeenCalledWith(tenant,id);expect(screen.getByLabelText('Journey name')).toHaveValue(draft.name);expect(screen.getByLabelText('Journey accent')).toHaveValue(draft.presentation.accentColor);expect(screen.getByLabelText('Journey layout')).toHaveValue('compact');});
it('ignores a foreign tenant URL locator and starts a fresh dedicated draft after explicit review',async()=>{window.history.replaceState(null,'','/?journeyTenant='+other+'&journeyDraft='+flow);const {client}=fixture();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();expect(screen.getByLabelText('Journey draft ID')).toHaveValue('');edit();fireEvent.click(screen.getByRole('button',{name:'Start new journey draft'}));expect(screen.getByLabelText('Journey name')).toHaveValue('New housekeeping draft');fireEvent.click(screen.getByRole('button',{name:'Discard edits and change journey ID'}));expect(screen.getByLabelText('Journey name')).toHaveValue('');expect(new URL(window.location.href).searchParams.get('journeyDraft')).toBeNull();expect(client.savePaidJourneyDraft).not.toHaveBeenCalled();});
it.each(['profile','load','save'] as const)('drops late %s results after same-client auth changes even without rerender',async kind=>{const {client,changeAuth}=fixture();let finish!:(value:unknown)=>void;render(<ConnectedPaidJourneyDraft {...props} client={client}/>);if(kind==='profile'){vi.mocked(client.businessProfile).mockImplementation(()=>new Promise(resolve=>finish=resolve as typeof finish));fireEvent.click(screen.getByRole('button',{name:'Check journey editor availability'}));}else{await open();if(kind==='load'){vi.mocked(client.loadPaidJourneyDraft).mockImplementation(()=>new Promise(resolve=>finish=resolve as typeof finish));fireEvent.change(screen.getByLabelText('Journey draft ID'),{target:{value:flow}});fireEvent.click(screen.getByRole('button',{name:'Reload saved journey draft'}));}else{edit();vi.mocked(client.savePaidJourneyDraft).mockImplementation(()=>new Promise(resolve=>finish=resolve as typeof finish));fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));}}await waitFor(()=>expect(finish).toBeTypeOf('function'));changeAuth();finish(kind==='profile'?profile:kind==='load'?draft:{schemaVersion:1,tenantId:tenant,flowId:flow,revision:1});await new Promise(resolve=>setTimeout(resolve,0));expect(screen.queryByText('Loaded journey draft revision 2.')).toBeNull();expect(screen.queryByText(/Saved journey draft revision 1/)).toBeNull();expect(new URL(window.location.href).searchParams.get('journeyDraft')).toBeNull();});

it.each(['client','unmount'] as const)('drops pending loaded private fields on %s replacement',async kind=>{const {client}=fixture();let finish!:(value:PaidJourneyOwnerDraft)=>void;const view=render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();vi.mocked(client.loadPaidJourneyDraft).mockImplementation(()=>new Promise(resolve=>finish=resolve));fireEvent.change(screen.getByLabelText('Journey draft ID'),{target:{value:flow}});fireEvent.click(screen.getByRole('button',{name:'Reload saved journey draft'}));await waitFor(()=>expect(finish).toBeTypeOf('function'));if(kind==='unmount')view.unmount();else view.rerender(<ConnectedPaidJourneyDraft {...props} client={fixture().client}/>);finish(draft);await new Promise(resolve=>setTimeout(resolve,0));expect(document.body.textContent).not.toContain(draft.name);expect(screen.queryByLabelText('Journey name')).toBeNull();});
it('preserves rejected unsupported-service edits and does not automatically retry the server authority',async()=>{const {client}=fixture();vi.mocked(client.savePaidJourneyDraft).mockRejectedValue(new PaidJourneyDraftError('rejected','private catalog details'));render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();edit();fireEvent.click(screen.getByRole('button',{name:'Save journey draft'}));await screen.findByText(/The server rejected this journey draft/);expect(screen.getByLabelText('Journey name')).toHaveValue('New housekeeping draft');expect(client.savePaidJourneyDraft).toHaveBeenCalledTimes(1);expect(client.loadPaidJourneyDraft).not.toHaveBeenCalled();expect(document.body.textContent).not.toContain('private catalog details');});

const publishedId='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',installation='ffffffff-ffff-4fff-8fff-ffffffffffff';
function publicationFixture(){const base=fixture();let state:PaidJourneyPublicationState={phase:'ready'};const receipt:PaidJourneyPublicationReceipt={schemaVersion:1,tenantId:tenant,flowId:flow,draftRevision:2,versionId:publishedId,installationId:installation,renderSchemaVersion:8,replayed:false};const client:JourneyDraftClient={...base.client,simpleOfferLocked:()=>base.client.simpleOfferLocked()||state.phase==='unknown'||state.phase==='publishing',paidJourneyPublicationState:()=>state,publishPaidJourneyDraft:vi.fn(async()=>{state={phase:'published',flowId:flow,draftRevision:2,receipt};return receipt;}),readPaidJourneyRender:vi.fn(async()=>({renderSchemaVersion:8 as const,submissionMode:'paid_journey_request' as const,paymentMode:'staging_mock' as const,simulated:true as const,versionId:publishedId,service:{id:serviceId,name:'Cleaning visit',durationMinutes:60,price:{amount:12500,currency:'USD'}},form:{name:draft.name,presentation:draft.presentation,journey:draft.journey}}))};return {...base,client,receipt,setPublication:(value:PaidJourneyPublicationState)=>state=value};}
async function reviewPublication(){fireEvent.change(screen.getByLabelText('Journey approved browser origins'),{target:{value:'https://checkout.example.test'}});fireEvent.click(screen.getByRole('button',{name:'Review journey publication'}));await screen.findByRole('region',{name:'Review saved journey publication'});}
it('publishes a saved unchanged journey only after exact-origin review and explicit confirmation, shows truthful snapshot verification pending without an install claim',async()=>{const {client}=publicationFixture();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();expect(screen.getByRole('button',{name:'Review journey publication'})).toBeDisabled();await load();expect(client.publishPaidJourneyDraft).not.toHaveBeenCalled();await reviewPublication();expect(client.publishPaidJourneyDraft).not.toHaveBeenCalled();fireEvent.click(screen.getByRole('button',{name:'Confirm journey publication'}));await screen.findByText('Journey snapshot published. Customer checkout remains pending.');expect(client.publishPaidJourneyDraft).toHaveBeenCalledWith(tenant,flow,{schemaVersion:1,expectedDraftRevision:2,allowedOrigins:['https://checkout.example.test']});expect(screen.getByText(publishedId)).toBeVisible();expect(screen.getByText(installation)).toBeVisible();expect(screen.queryByRole('link')).toBeNull();expect(screen.getByText(/Authenticated owner snapshot verification is pending/)).toBeVisible();expect(client.readPaidJourneyRender).not.toHaveBeenCalled();expect(client.publishPaidJourneyDraft).toHaveBeenCalledTimes(1);});
it.each(['*','https://*.example.test','https://checkout.*','http://checkout.example.test','https://checkout.example.test/path','https://user:pass@checkout.example.test','https://checkout.example.test,https://checkout.example.test',''])('rejects unsupported exact origin %s without a publication request',async origin=>{const {client}=publicationFixture();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();fireEvent.change(screen.getByLabelText('Journey approved browser origins'),{target:{value:origin}});fireEvent.click(screen.getByRole('button',{name:'Review journey publication'}));expect(screen.getByText(/Enter one or more unique exact HTTPS/)).toBeVisible();expect(client.publishPaidJourneyDraft).not.toHaveBeenCalled();});
it('invalidates a publication review on dirty edits and requires saving before another review',async()=>{const {client}=publicationFixture();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();await reviewPublication();fireEvent.change(screen.getByLabelText('Journey name'),{target:{value:'Unsaved different journey'}});expect(screen.queryByRole('button',{name:'Confirm journey publication'})).toBeNull();expect(screen.getByRole('button',{name:'Review journey publication'})).toBeDisabled();expect(client.publishPaidJourneyDraft).not.toHaveBeenCalled();});
it('locks unknown publication outcomes and cannot reconcile the writer by reading a render',async()=>{const {client,setPublication}=publicationFixture();vi.mocked(client.publishPaidJourneyDraft!).mockImplementation(async()=>{setPublication({phase:'unknown',flowId:flow,draftRevision:2});throw new PublicationError('unknown','private response details');});render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();await reviewPublication();fireEvent.click(screen.getByRole('button',{name:'Confirm journey publication'}));await screen.findByText(/All replacement writers remain locked/);expect(screen.getByRole('button',{name:'Review journey publication'})).toBeDisabled();expect(client.publishPaidJourneyDraft).toHaveBeenCalledTimes(1);expect(client.readPaidJourneyRender).not.toHaveBeenCalled();expect(document.body.textContent).not.toContain('private response details');});
it.each(['tenant','auth','unmount'] as const)('drops a late publication receipt on %s change',async kind=>{const {client,changeAuth,receipt}=publicationFixture();let finish!:(value:PaidJourneyPublicationReceipt)=>void;vi.mocked(client.publishPaidJourneyDraft!).mockImplementation(()=>new Promise(resolve=>finish=resolve));const view=render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();await reviewPublication();fireEvent.click(screen.getByRole('button',{name:'Confirm journey publication'}));await waitFor(()=>expect(finish).toBeTypeOf('function'));if(kind==='tenant')view.rerender(<ConnectedPaidJourneyDraft {...props} tenantId={other} services={[{...service,tenant_id:other}]} client={client}/>);else if(kind==='auth'){changeAuth();view.rerender(<ConnectedPaidJourneyDraft {...props} client={client}/>);}else view.unmount();finish(receipt);await new Promise(resolve=>setTimeout(resolve,0));expect(document.body.textContent).not.toContain(publishedId);expect(screen.queryByText('Journey snapshot published. Customer checkout remains pending.')).toBeNull();});

