async function actualHistoryClient(payment:'success'|'unknown'|'forged'='success'){
 let history=versionHistory;const json=(value:unknown)=>new Response(JSON.stringify(value),{status:200});
 const transport=vi.fn<typeof fetch>(async(url,request)=>{const path=String(url);if(path.includes('/auth/v1/token'))return json({access_token:'synthetic-owner-token'});if(path.includes('/auth/v1/user'))return json({id:other});if(path.includes('/api/business-profile?'))return json(profile.status==='initialized'?{ok:true,data:profile.profile}:{});if(path.includes('/draft?'))return json({ok:true,data:draft});if(path.includes('/versions?'))return json({ok:true,data:history});if(path.includes('/rollback?')){if(payment==='unknown')throw Error('private transport token');if(payment==='forged')return json({ok:true,data:{...rollbackReceipt,installationId:installation}});history={...versionHistory,versions:versionHistory.versions.map(v=>({...v,current:v.versionId===other}))};return json({ok:true,data:rollbackReceipt});}throw Error('unexpected private path '+request?.method);});
 const client=createRuntimeClient({url:'https://example.supabase.co',publishableKey:'sb_publishable_synthetic',tenantId:tenant,bookingApiOrigin:'https://api.example.test'},transport);await client.signIn('owner@example.test','synthetic');return{client,transport};
}
it('uses actual SDK owner transport: explicit GET, immutable CAS POST once, original independent form URL',async()=>{const {client,transport}=await actualHistoryClient();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();await reviewRestore();expect(transport.mock.calls.filter(([url])=>String(url).includes('/rollback?'))).toHaveLength(0);fireEvent.click(screen.getByRole('button',{name:'Confirm restore revision 1'}));await screen.findByRole('region',{name:'Journey rollback receipt'});const request=transport.mock.calls.find(([url])=>String(url).includes('/rollback?'))!;expect(String(request[0])).toBe('https://api.example.test/api/paid-journey-flows/'+flow+'/rollback?tenantId='+tenant);expect(request[1]).toMatchObject({method:'POST',credentials:'omit',cache:'no-store',redirect:'error',referrerPolicy:'no-referrer'});expect(JSON.parse(request[1]!.body as string)).toEqual({expectedCurrentVersionId:publishedId,targetVersionId:other});expect(new Headers(request[1]?.headers).get('Authorization')).toBe('Bearer synthetic-owner-token');expect(new Headers(request[1]?.headers).has('Origin')).toBe(false);expect(transport.mock.calls.filter(([url])=>String(url).includes('/rollback?'))).toHaveLength(1);expect(client.paidJourneyRollbackState(tenant).phase).toBe('verified');expect(client.paidJourneyDraftState(tenant).phase).toBe('loaded');expect(document.body.textContent).not.toContain('synthetic-owner-token');});
it.each(['unknown','forged'] as const)('actual SDK preserves %s rollback uncertainty after a successful owner history read',async kind=>{const {client,transport}=await actualHistoryClient(kind);render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();await reviewRestore();fireEvent.click(screen.getByRole('button',{name:'Confirm restore revision 1'}));await screen.findByText('Rollback outcome is unverified. Do not repeat or replace this write.');await readHistory();expect(client.paidJourneyRollbackState(tenant).phase).toBe('unknown');expect(client.simpleOfferLocked()).toBe(true);expect(screen.getByRole('button',{name:'Review restore revision 1'})).toBeDisabled();expect(screen.getByRole('button',{name:'Save journey draft'})).toBeDisabled();expect(screen.queryByRole('region',{name:'Journey rollback receipt'})).toBeNull();expect(transport.mock.calls.filter(([url])=>String(url).includes('/rollback?'))).toHaveLength(1);expect(document.body.textContent).not.toContain('private transport token');});

it.each(['read','rollback'] as const)('actual SDK rejects late %s authority after same-owner sign-out/sign-in without A-B-A revival',async kind=>{const {client,transport}=await actualHistoryClient();const original=transport.getMockImplementation()!;let finish!:(value:Response)=>void;transport.mockImplementation((url,request)=>String(url).includes(kind==='read'?'/versions?':'/rollback?')?new Promise<Response>(resolve=>finish=resolve):original(url,request));const view=render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();if(kind==='read')fireEvent.click(screen.getByRole('button',{name:'Read journey version history'}));else{transport.mockImplementation((url,request)=>String(url).includes('/rollback?')?new Promise<Response>(resolve=>finish=resolve):original(url,request));await reviewRestore();fireEvent.click(screen.getByRole('button',{name:'Confirm restore revision 1'}));}await waitFor(()=>expect(finish).toBeTypeOf('function'));client.signOut();await client.signIn('owner@example.test','synthetic');view.rerender(<ConnectedPaidJourneyDraft {...props} client={client}/>);finish(new Response(JSON.stringify({ok:true,data:kind==='read'?versionHistory:rollbackReceipt}),{status:200}));await new Promise(resolve=>setTimeout(resolve,0));expect(screen.queryByRole('region',{name:'Journey rollback receipt'})).toBeNull();expect(document.body.textContent).not.toContain('Original journey');expect(screen.queryByRole('button',{name:'Confirm restore revision 1'})).toBeNull();if(kind==='rollback'){expect(client.paidJourneyRollbackState(tenant).phase).toBe('unknown');expect(client.simpleOfferLocked()).toBe(true);}expect(transport.mock.calls.filter(([url])=>String(url).includes('/rollback?'))).toHaveLength(kind==='rollback'?1:0);});
it('actual SDK retains unknown writer across an editor remount while permitting only explicit history evidence',async()=>{const {client,transport}=await actualHistoryClient('unknown');const initial=render(<ConnectedPaidJourneyDraft {...props} client={client}/>);await open();await load();await reviewRestore();fireEvent.click(screen.getByRole('button',{name:'Confirm restore revision 1'}));await screen.findByText('Rollback outcome is unverified. Do not repeat or replace this write.');initial.unmount();render(<ConnectedPaidJourneyDraft {...props} client={client}/>);expect(screen.getByRole('button',{name:'Check journey editor availability'})).toBeDisabled();await readHistory();expect(screen.getByRole('button',{name:'Review restore revision 1'})).toBeDisabled();expect(client.paidJourneyRollbackState(tenant).phase).toBe('unknown');expect(transport.mock.calls.filter(([url])=>String(url).includes('/rollback?'))).toHaveLength(1);expect(screen.queryByRole('region',{name:'Journey rollback receipt'})).toBeNull();});

it('clears already displayed private history on client replacement even with the same flow and auth revision',async()=>{const first=historyFixture(),second=historyFixture();const view=render(<ConnectedPaidJourneyDraft {...props} client={first.client}/>);await open();await load();await readHistory();expect(screen.getByText(/Current journey - revision 2/)).toBeVisible();view.rerender(<ConnectedPaidJourneyDraft {...props} client={second.client}/>);await waitFor(()=>expect(screen.queryByText(/Current journey - revision 2/)).toBeNull());expect(second.client.paidJourneyVersionHistory).not.toHaveBeenCalled();expect(screen.queryByRole('link')).toBeNull();});

it('keeps a dispatched restore uncertain across same-auth client replacement and blocks a second rollback',async()=>{const first=historyFixture(),second=historyFixture();let finish!:(value:PaidJourneyRollbackReceipt)=>void;vi.mocked(first.client.rollbackPaidJourney!).mockImplementation(()=>new Promise(resolve=>finish=resolve));const view=render(<ConnectedPaidJourneyDraft {...props} client={first.client}/>);await open();await load();await reviewRestore();fireEvent.click(screen.getByRole('button',{name:'Confirm restore revision 1'}));await waitFor(()=>expect(finish).toBeTypeOf('function'));view.rerender(<ConnectedPaidJourneyDraft {...props} client={second.client}/>);await readHistory();expect(screen.getByRole('button',{name:'Review restore revision 1'})).toBeDisabled();expect(second.client.rollbackPaidJourney).not.toHaveBeenCalled();finish(rollbackReceipt);await new Promise(resolve=>setTimeout(resolve,0));expect(screen.queryByRole('region',{name:'Journey rollback receipt'})).toBeNull();expect(first.client.rollbackPaidJourney).toHaveBeenCalledTimes(1);});
